// Minimal HTMX-like fallback for core features used by this app:
// - hx-get: fetch URL and place response into hx-target using innerHTML
// - hx-post: submit form via fetch and swap target
// This is a tiny polyfill to allow basic modal loading when htmx.org cannot be loaded.
(function(){
    if(window.htmx) return; // real htmx already present
    window.htmx = { version: '0.0.0-fallback' };

    function swapContent(targetSelector, html){
        try{
            var target = document.querySelector(targetSelector);
            if(!target) return;
            target.innerHTML = html;
        }catch(e){ console.error('htmx-fallback swap error', e); }
    }

    document.addEventListener('click', function(evt){
        var el = evt.target.closest('[hx-get]');
        if(!el) return;
        evt.preventDefault();
        var url = el.getAttribute('hx-get') || el.getAttribute('href');
        var target = el.getAttribute('hx-target') || '#modal-container';
        fetch(url, { credentials: 'same-origin' })
            .then(function(res){ return res.text(); })
            .then(function(html){ swapContent(target, html); })
            .catch(function(err){ console.error('htmx-fallback hx-get failed', err); });
    }, true);

    document.addEventListener('submit', function(evt){
        var form = evt.target.closest('form[hx-post]');
        if(!form) return;
        evt.preventDefault();
        var url = form.getAttribute('hx-post') || form.getAttribute('action');
        var target = form.getAttribute('hx-target') || '#modal-container';
        var formData = new FormData(form);
        fetch(url, {
            method: 'POST',
            credentials: 'same-origin',
            body: formData
        })
        .then(function(res){ return res.text(); })
        .then(function(html){
            // if server returned 204 No Content, try to redirect via Location header
            swapContent(target, html);
        })
        .catch(function(err){ console.error('htmx-fallback hx-post failed', err); });
    }, true);

    // Initialize: attach role to elements with hx-get/hx-post so users can see it's active
    document.addEventListener('DOMContentLoaded', function(){
        var elems = document.querySelectorAll('[hx-get], form[hx-post]');
        if(elems.length) console.debug('htmx fallback active, handling', elems.length, 'elements');
    });
})();
